#include <iostream>
#include <memory>
#include <new>

struct PreparacionFallida {};

class Caja {
public:
    bool hay() const { return actual_ != nullptr; }
    int valor() const { return *actual_; }
    bool cambiar(int valor);
    bool vaciar();
    bool reponer(int valor, bool provocarFallo);
private:
    std::unique_ptr<int> actual_;
};

bool Caja::cambiar(int valor) {
    if (!actual_ || valor < 0 || valor > 9) {
        return false;
    }
    *actual_ = valor;
    return true;
}

bool Caja::vaciar() {
    actual_.reset();
    return true;
}

bool Caja::reponer(int valor, bool provocarFallo) {
    if (valor < 0 || valor > 9) {
        return false;
    }
    // Completa el candidato propietario, el fallo de prueba, el intercambio y las capturas.
    (void)provocarFallo;
    return false;
}

void mostrar(const Caja& caja) {
    if (caja.hay()) {
        std::cout << caja.valor();
    } else {
        std::cout << 'X';
    }
}

int main() {
    int cantidadOrdenes = 0;
    if (!(std::cin >> cantidadOrdenes) || cantidadOrdenes < 1 || cantidadOrdenes > 12) {
        return 1;
    }
    Caja caja;
    std::cout << "Inicio:";
    mostrar(caja);
    std::cout << '\n';
    for (int i = 0; i < cantidadOrdenes; ++i) {
        int operacion = 0;
        int valor = 0;

        if (!(std::cin >> operacion >> valor)) {
            return 1;
        }
        const bool habia = caja.hay();
        const int anterior = habia ? caja.valor() : 0;
        bool aceptado = false;

        if (operacion == 1 || operacion == 2) {
            aceptado = caja.reponer(valor, operacion == 2);
        } else if (operacion == 3) {
            aceptado = caja.cambiar(valor);
        } else if (operacion == 4) {
            aceptado = caja.vaciar();
        }
        std::cout << "Resultado:" << aceptado << ";Antes:";
        if (habia) {
            std::cout << anterior;
        } else {
            std::cout << 'X';
        }
        std::cout << ";Actual:";
        mostrar(caja);
        std::cout << '\n';
    }
    std::cout << "Final:";
    mostrar(caja);
    return 0;
}

